import{_ as a,o as t,c as s,ae as i}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"State Contract（状态读写合同）","description":"","frontmatter":{},"headers":[],"relativePath":"reference/contracts/state-contract.md","filePath":"reference/contracts/state-contract.md"}'),o={name:"reference/contracts/state-contract.md"};function n(l,e,r,d,c,h){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="state-contract-状态读写合同" tabindex="-1">State Contract（状态读写合同） <a class="header-anchor" href="#state-contract-状态读写合同" aria-label="Permalink to &quot;State Contract（状态读写合同）&quot;">​</a></h1><blockquote><p>Defines the interface for omm state persistence: key format, value schema, atomic write guarantee, and validation rules.</p></blockquote><h2 id="key-format" tabindex="-1">Key Format <a class="header-anchor" href="#key-format" aria-label="Permalink to &quot;Key Format&quot;">​</a></h2><ul><li>Keys are plain strings used as filenames: <code>{stateRoot}/state/{key}.json</code></li><li>Default <code>stateRoot</code>: <code>~/.openclaw/omm</code> (configurable via <code>api.config.stateRoot</code> or <code>OMM_STATE_ROOT</code> env var)</li><li>Key must be a non-empty string after trimming</li><li>No path separators or special characters enforced (filesystem constraints apply)</li></ul><h2 id="value-schema" tabindex="-1">Value Schema <a class="header-anchor" href="#value-schema" aria-label="Permalink to &quot;Value Schema&quot;">​</a></h2><ul><li>Value must be a non-null, non-array JSON object (<code>typeof value === &quot;object&quot; &amp;&amp; value !== null &amp;&amp; !Array.isArray(value)</code>)</li><li>All values receive a <code>lastUpdatedAt</code> ISO8601 timestamp on every write</li><li>Mode-aware validation applies when <code>value.mode</code> or <code>key</code> matches a known mode</li></ul><h2 id="atomic-write-guarantee-原子写入保证" tabindex="-1">Atomic Write Guarantee（原子写入保证） <a class="header-anchor" href="#atomic-write-guarantee-原子写入保证" aria-label="Permalink to &quot;Atomic Write Guarantee（原子写入保证）&quot;">​</a></h2><p>All writes use a two-step atomic pattern:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>writeFile(&quot;{key}.json.tmp&quot;, data, &quot;utf8&quot;)</span></span>
<span class="line"><span>rename(&quot;{key}.json.tmp&quot;, &quot;{key}.json&quot;)</span></span></code></pre></div><ul><li>Directory is created with <code>recursive: true</code> on first write</li><li><code>rename()</code> is atomic on POSIX; on Windows it is atomic within the same volume</li><li>No file locking — concurrent writers to the same key may race (last-write-wins)</li></ul><h2 id="validation-rules-验证规则" tabindex="-1">Validation Rules（验证规则） <a class="header-anchor" href="#validation-rules-验证规则" aria-label="Permalink to &quot;Validation Rules（验证规则）&quot;">​</a></h2><h3 id="dispatch-logic" tabindex="-1">Dispatch Logic <a class="header-anchor" href="#dispatch-logic" aria-label="Permalink to &quot;Dispatch Logic&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mode = value.mode ?? key</span></span>
<span class="line"><span>validator = VALIDATORS[mode]  // ralph | autopilot | team</span></span>
<span class="line"><span>if (validator) → mode-specific validation</span></span>
<span class="line"><span>else → pass through with lastUpdatedAt only</span></span></code></pre></div><h3 id="known-modes" tabindex="-1">Known Modes <a class="header-anchor" href="#known-modes" aria-label="Permalink to &quot;Known Modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>Validator</th><th>Status Field</th></tr></thead><tbody><tr><td><code>ralph</code></td><td><code>validateRalph()</code></td><td><code>status</code></td></tr><tr><td><code>autopilot</code></td><td><code>validateAutopilot()</code></td><td><code>status</code></td></tr><tr><td><code>team</code></td><td><code>validateTeam()</code></td><td><code>current_phase</code></td></tr></tbody></table><p>See <a href="./workflow-state-contract.html">Workflow State Contract</a> for mode-specific rules.</p><h3 id="shared-validation-rules" tabindex="-1">Shared Validation Rules <a class="header-anchor" href="#shared-validation-rules" aria-label="Permalink to &quot;Shared Validation Rules&quot;">​</a></h3><ol><li><strong>Phase normalization</strong>: status/phase strings are trimmed and lowercased</li><li><strong>Phase membership</strong>: must belong to the mode&#39;s valid phase set</li><li><strong>Terminal enforcement</strong>: <code>{complete, failed, blocked}</code> require <code>active=false</code></li><li><strong>Auto-completion</strong>: terminal phases get <code>completedAt</code> auto-set if missing</li><li><strong>Timestamp validation</strong>: <code>startedAt</code>, <code>completedAt</code>, <code>lastUpdatedAt</code> must be valid ISO8601 when present</li><li><strong>Default injection</strong>: when <code>active=true</code>, missing counters and status receive sensible defaults</li><li><strong>Counter validation</strong>: counters must be non-negative integers; max values must be positive integers</li></ol><h3 id="unknown-keys" tabindex="-1">Unknown Keys <a class="header-anchor" href="#unknown-keys" aria-label="Permalink to &quot;Unknown Keys&quot;">​</a></h3><p>Keys that don&#39;t match any known mode pass through without business validation. Only <code>lastUpdatedAt</code> is added.</p><h2 id="return-type" tabindex="-1">Return Type <a class="header-anchor" href="#return-type" aria-label="Permalink to &quot;Return Type&quot;">​</a></h2><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">interface</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> StateValidationResult</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  ok</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> boolean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  state</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Record</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">unknown</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// validated + normalized state (on success)</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  warning</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// non-fatal warning</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  error</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// validation error message (on failure)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="dual-access-model-双通道访问模型" tabindex="-1">Dual-Access Model（双通道访问模型） <a class="header-anchor" href="#dual-access-model-双通道访问模型" aria-label="Permalink to &quot;Dual-Access Model（双通道访问模型）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Access Path</th><th>Entry Point</th><th>Validation</th></tr></thead><tbody><tr><td>In-process (plugin)</td><td><code>omm_state_write</code> tool</td><td>Full <code>validateStateWrite()</code></td></tr><tr><td>Out-of-process (MCP)</td><td><code>omm_state_write</code> via JSON-RPC</td><td>Inline simplified validation</td></tr></tbody></table><p>Both paths write to the same directory. The MCP server&#39;s validation is a simplified subset: it checks phase membership and terminal rules but does not inject defaults or validate counters.</p><h2 id="error-contract" tabindex="-1">Error Contract <a class="header-anchor" href="#error-contract" aria-label="Permalink to &quot;Error Contract&quot;">​</a></h2><ul><li>Plugin tools return errors in the content array: <code>{ content: [{ type: &quot;text&quot;, text: &quot;omm_state_write error: ...&quot; }] }</code></li><li>MCP server returns JSON-RPC error: <code>{ error: { code: -32000, message: &quot;...&quot; } }</code></li></ul>`,27)])])}const k=a(o,[["render",n]]);export{u as __pageData,k as default};
